etalage.css:
body{font-family:'Archivo','Segoe UI',Arial,sans-serif;}
h1,h2,h3{font-weight:800;letter-spacing:-.025em;}
.btn,.menu a.cta{border-radius:4px;}
.hero::after{display:none;}
.hero.has-photo{background-color:#000;background-size:cover;background-position:center;min-height:min(88vh,780px);display:flex;align-items:flex-end;padding-top:140px;}
.hero.has-photo::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.82) 0%,rgba(0,0,0,.6) 45%,rgba(0,0,0,.2) 100%),linear-gradient(180deg,rgba(0,0,0,0) 40%,rgba(0,0,0,.6) 100%);}
.hero.has-photo .wrap{grid-template-columns:1fr;width:100%;}
.hero.has-photo .emblem{display:none;}
.hero.has-photo .lead{color:rgba(255,255,255,.88);}
.hero h1{font-size:clamp(44px,7.6vw,96px);max-width:16ch;}
.service{border-radius:4px;} .service .num{border-radius:4px;}
.folder{padding-top:0;} .folder .tab{display:none;}
.folder .body{border-radius:6px;min-height:560px;background:#000 !important;}
.folder .body::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,rgba(0,0,0,0) 35%,rgba(0,0,0,.85) 100%);}
.folder .photo-sheet{inset:0;top:0;left:0;right:0;height:auto;transform:none;border-radius:0;padding:0;box-shadow:none;}
.folder .photo-sheet img{border-radius:0;transition:transform .5s ease;}
.folder:hover .photo-sheet{transform:none;} .folder:hover .photo-sheet img{transform:scale(1.04);}
.folder .photo-sheet.empty{background:var(--navy);}
.folder .front{z-index:2;} .folder .desc{color:rgba(255,255,255,.85);}
.cards{grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:30px;}
.card{border:0;border-radius:0;background:transparent;}
.card:hover{transform:none;} .card .img{aspect-ratio:3/2;border-radius:4px;}
.card .img img{transition:transform .5s ease;} .card:hover .img img{transform:scale(1.04);}
.card .txt{padding:16px 2px 0;}
.section.sky,.sec.sky{background:#fff;}
.gallery{columns:2 420px;column-gap:22px;} .gallery .ph{border-radius:4px;}
@media (max-width:520px){.cards{grid-template-columns:1fr;}}

